import{_ as t,c as a,o,al as r}from"./chunks/framework.DM883ANZ.js";const m=JSON.parse('{"title":"Parameters over MAVLink FTP","description":"Parameters over MAVLink FTP — MAVLink message, enum and command reference.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Parameters over MAVLink FTP"}],["meta",{"property":"og:description","content":"Parameters over MAVLink FTP — MAVLink message, enum and command reference."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://mavlink.io/ko/services/parameter_ftp.html"}],["link",{"rel":"canonical","href":"https://mavlink.io/ko/services/parameter_ftp.html"}]]},"headers":[],"relativePath":"ko/services/parameter_ftp.md","filePath":"ko/services/parameter_ftp.md","lastUpdated":1789276941000}'),d={name:"ko/services/parameter_ftp.md"};function s(i,e,n,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="ftp" tabindex="-1">Parameters over MAVLink FTP <a class="header-anchor" href="#ftp" aria-label="Permalink to &quot;Parameters over MAVLink FTP {#ftp}&quot;">​</a></h1><p>The parameter protocol sends one MAVLink message per parameter. On a vehicle with a thousand parameters, and on a low bandwidth link such as a telemetry radio, a full <a href="./../services/parameter.html#read_all">read-all</a> can take a while and saturate the link (<code>PARAM_VALUE</code> is unacknowledged, so lost messages must be detected by timeout and individually re-requested).</p><p>As an optimisation, a component may additionally expose its whole parameter set as a single virtual file that is downloaded using the <a href="./../services/ftp.html">File Transfer Protocol (FTP)</a>. The file is a compact binary encoding of every parameter (name, type, value, and optionally its default value), transferred with FTP&#39;s acknowledged burst reads, which makes a full parameter sync roughly an order of magnitude faster and robust against packet loss.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This mechanism was originally defined and implemented by ArduPilot, and has been supported by <em>QGroundControl</em> and <em>MAVProxy</em> for a number of years. PX4 added support in <a href="https://github.com/PX4/PX4-Autopilot/pull/28435" target="_blank" rel="noreferrer">PX4-Autopilot#28435</a>. It complements, but does not replace, the <a href="./../services/parameter.html#parameter-operations">message-based protocol</a>: parameters are still <em>written</em> individually with <a href="./../services/parameter.html#PARAM_SET">PARAM_SET</a>, and changes are still notified with <a href="./../services/parameter.html#PARAM_VALUE">PARAM_VALUE</a>.</p></div><h2 id="ftp_path" tabindex="-1">File Path <a class="header-anchor" href="#ftp_path" aria-label="Permalink to &quot;File Path {#ftp_path}&quot;">​</a></h2><p>The parameter file is exposed at the <a href="./../services/ftp.html#virtual-directory-entries-directory-alias">virtual directory</a> path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@PARAM/param.pck</span></span></code></pre></div><p>The path may be followed by an optional URI-style query string, with <code>&amp;</code>-separated <code>key=value</code> pairs:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>start</code></td><td>0</td><td>Index of the first parameter to include (0-based, in the component&#39;s own parameter order).</td></tr><tr><td><code>count</code></td><td>0</td><td>Maximum number of parameters to include. <code>0</code> means &quot;all parameters from <code>start</code> to the end&quot;.</td></tr><tr><td><code>withdefaults</code></td><td>0</td><td>If <code>1</code>, include each parameter&#39;s default value where it differs from the current value, and use the <code>0x671C</code> <a href="#ftp_header">magic</a>.</td></tr></tbody></table><p>For example, the request used by <em>QGroundControl</em> and <em>MAVProxy</em> is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@PARAM/param.pck?withdefaults=1</span></span></code></pre></div><p>Servers must accept the bare path and should treat unknown keys as ignorable. A query that cannot be satisfied (for example <code>start</code> beyond the last parameter) should be rejected by NAKing the open with <a href="./../services/ftp.html#error_codes">FailErrno</a>/<code>EINVAL</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Existing clients only ever download the complete set, and reject a file whose <code>num_params</code> and <code>total_params</code> <a href="#ftp_header">header fields</a> differ. <code>start</code> and <code>count</code> are therefore only usable against a server and client that have agreed to support partial downloads.</p></div><h2 id="ftp_discovery" tabindex="-1">Support Discovery <a class="header-anchor" href="#ftp_discovery" aria-label="Permalink to &quot;Support Discovery {#ftp_discovery}&quot;">​</a></h2><p>There is no capability flag for this feature. A client detects support by simply opening <code>@PARAM/param.pck</code> with <a href="./../services/ftp.html#OpenFileRO">OpenFileRO</a>:</p><ul><li>An ACK means the component supports parameter download over FTP.</li><li>A NAK with <a href="./../services/ftp.html#error_codes">FileNotFound</a> means it does not, and the client should fall back to <a href="./../services/parameter.html#read_all">PARAM_REQUEST_LIST</a>.</li></ul><p>A client should also fall back if the transfer stalls or fails repeatedly, so that a partially-working FTP implementation cannot leave it without parameters.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The file exposes the parameters of the component that serves it. Current implementations only request it from the autopilot (<a href="./../messages/common.html#MAV_COMP_ID_AUTOPILOT1">MAV_COMP_ID_AUTOPILOT1</a>), and use <code>PARAM_REQUEST_LIST</code> for the other components of the system.</p></div><h2 id="ftp_format" tabindex="-1">File Format <a class="header-anchor" href="#ftp_format" aria-label="Permalink to &quot;File Format {#ftp_format}&quot;">​</a></h2><p>The file is a 6-byte header followed by one variable-length entry per parameter. All multi-byte fields are little-endian. There is no alignment requirement on entries; the only padding is the block padding <a href="#ftp_padding">described below</a>.</p><h3 id="ftp_header" tabindex="-1">Header <a class="header-anchor" href="#ftp_header" aria-label="Permalink to &quot;Header {#ftp_header}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Offset</th><th>Type</th><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>0</td><td><code>uint16_t</code></td><td><code>magic</code></td><td><code>0x671B</code> if entries carry values only, <code>0x671C</code> if entries may also carry default values (i.e. the request specified <code>withdefaults=1</code>).</td></tr><tr><td>2</td><td><code>uint16_t</code></td><td><code>num_params</code></td><td>Number of parameter entries in <em>this</em> file (i.e. after <code>start</code>/<code>count</code> have been applied).</td></tr><tr><td>4</td><td><code>uint16_t</code></td><td><code>total_params</code></td><td>For a download: the total number of parameters the component has. For an <a href="#ftp_upload">upload</a>: the total length of the file in bytes.</td></tr></tbody></table><p>A client must reject a file whose <code>magic</code> is neither value. When the whole set was requested (no <code>start</code>/<code>count</code>), <code>num_params</code> and <code>total_params</code> are equal, and a client can use either as the expected entry count.</p><h3 id="ftp_entry" tabindex="-1">Parameter Entry <a class="header-anchor" href="#ftp_entry" aria-label="Permalink to &quot;Parameter Entry {#ftp_entry}&quot;">​</a></h3><p>Each entry encodes the parameter&#39;s type, its name (delta-encoded against the previous entry), its value, and optionally its default value.</p><table tabindex="0"><thead><tr><th>Offset</th><th>Size</th><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>0</td><td>4 bits</td><td><code>type</code></td><td>Low nibble of byte 0: the <a href="#ftp_types">value type</a>.</td></tr><tr><td>0</td><td>4 bits</td><td><code>flags</code></td><td>High nibble of byte 0. Bit 0 set means a default value follows the value. All other bits are reserved and must be 0.</td></tr><tr><td>1</td><td>4 bits</td><td><code>common_len</code></td><td>Low nibble of byte 1: number of leading name characters shared with the previous entry&#39;s name (0-15). Always 0 for the first entry.</td></tr><tr><td>1</td><td>4 bits</td><td><code>name_len-1</code></td><td>High nibble of byte 1: number of name characters that follow, minus one (so 1-16 characters are encoded as 0-15).</td></tr><tr><td>2</td><td><code>name_len</code></td><td><code>name</code></td><td>The non-shared suffix of the parameter name (not null-terminated).</td></tr><tr><td>2+<code>name_len</code></td><td><code>type_len</code></td><td><code>value</code></td><td>The parameter value, in the encoding given by <code>type</code>.</td></tr><tr><td>...</td><td><code>type_len</code></td><td><code>default</code></td><td>Only present if <code>flags</code> bit 0 is set: the parameter&#39;s default value, same type and length as <code>value</code>.</td></tr></tbody></table><p>The full parameter name is <code>previous_name[0:common_len] + name</code>. <code>common_len + name_len</code> must not exceed 16 (the maximum <a href="./../services/parameter.html#parameter-names">parameter name</a> length); a client must reject an entry that violates this.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The encoding cannot express a zero-length suffix, so a name that is an exact prefix of the previous name is encoded with <code>common_len</code> reduced by one and <code>name_len</code> of 1 (the last shared character is re-sent).</p></div><h3 id="ftp_types" tabindex="-1">Value Types <a class="header-anchor" href="#ftp_types" aria-label="Permalink to &quot;Value Types {#ftp_types}&quot;">​</a></h3><p>The <code>type</code> field uses ArduPilot&#39;s internal parameter type numbering, which is <em>not</em> <a href="./../messages/common.html#MAV_PARAM_TYPE">MAV_PARAM_TYPE</a>:</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>Name</th><th><code>type_len</code></th><th>Encoding</th></tr></thead><tbody><tr><td>0</td><td>—</td><td>—</td><td>Not a valid entry type; a <code>0</code> first byte is <a href="#ftp_padding">padding</a>.</td></tr><tr><td>1</td><td><code>INT8</code></td><td>1</td><td><code>int8_t</code></td></tr><tr><td>2</td><td><code>INT16</code></td><td>2</td><td><code>int16_t</code></td></tr><tr><td>3</td><td><code>INT32</code></td><td>4</td><td><code>int32_t</code></td></tr><tr><td>4</td><td><code>FLOAT</code></td><td>4</td><td>IEEE-754 single-precision</td></tr></tbody></table><p>A client must reject a file containing any other type value.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A component only emits the types it actually uses: ArduPilot emits all four, PX4 emits only <code>INT32</code> and <code>FLOAT</code>. Vector-valued parameters are flattened into their scalar components, each with its own name and entry.</p></div><h3 id="ftp_padding" tabindex="-1">Block Padding <a class="header-anchor" href="#ftp_padding" aria-label="Permalink to &quot;Block Padding {#ftp_padding}&quot;">​</a></h3><p>Parameter values are read from the live parameter store as the file is generated, so a block that is re-read (after a lost burst message, for example) may be regenerated from a newer value. To ensure that a re-read can never splice two halves of two different values together, the file is padded so that a value never straddles a block boundary, where a <em>block</em> is <code>block_size</code> consecutive bytes of the file starting at offset 0 (the header is part of the first block).</p><p>Before writing an entry the server computes the file offset just past the unpadded entry, and if the entry&#39;s trailing value would cross into the next block, inserts that many zero bytes before the entry:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>end     = entry_offset + entry_len          # file offset just past the entry</span></span>
<span class="line"><span>end_mod = end % block_size</span></span>
<span class="line"><span>if 0 &lt; end_mod &lt; value_len:</span></span>
<span class="line"><span>    pad = value_len - end_mod               # zero bytes written before the entry</span></span></code></pre></div><p>A client must skip zero bytes wherever an entry is expected. This is unambiguous because <code>type</code> 0 is not a valid entry type, so the first byte of a real entry is never zero.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>block_size</code> must be the size of every read the client issues on the session, because the padding shifts every subsequent entry. ArduPilot latches the size of the first <a href="./../services/ftp.html#ReadFile">ReadFile</a>/<a href="./../services/ftp.html#BurstReadFile">BurstReadFile</a> of the session and NAKs any later read with a different size; PX4 always uses 239.</p><p>Clients should therefore always request the maximum FTP data size of <strong>239 bytes</strong> for every read, including the read that hits the end of the file.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ArduPilot applies the rule to the entry&#39;s trailing field only (<code>value_len</code> is the length of one value, and with <code>withdefaults=1</code> the trailing field is the default). PX4 applies it to the value and default together (<code>value_len</code> is 8 when a default is present), which is stricter. Both produce files that a conforming client decodes identically, since pad bytes are simply skipped.</p></div><h2 id="ftp_download" tabindex="-1">Downloading Parameters <a class="header-anchor" href="#ftp_download" aria-label="Permalink to &quot;Downloading Parameters {#ftp_download}&quot;">​</a></h2><p>The download is an ordinary FTP <a href="./../services/ftp.html#reading-a-file-burstreadfile">burst read</a> (or <a href="./../services/ftp.html#reading-a-file-readfile">read</a>) of the virtual file:</p><ol><li>Client sends <a href="./../services/ftp.html#OpenFileRO">OpenFileRO</a> with <code>data</code> set to <code>@PARAM/param.pck</code> plus any <a href="#ftp_path">query string</a>. <ul><li>NAK with <code>FileNotFound</code> means the feature is not supported; fall back to <a href="./../services/parameter.html#read_all">PARAM_REQUEST_LIST</a>.</li></ul></li><li>Client reads the file with <code>BurstReadFile</code> (preferred) or <code>ReadFile</code>, always using a read size of 239 bytes, and re-requests any missing chunks.</li><li>Client sends <a href="./../services/ftp.html#TerminateSession">TerminateSession</a>.</li><li>Client parses the file and populates its <a href="./../services/parameter.html#parameter_caching">parameter cache</a>.</li></ol><p>The client should then track subsequent changes by monitoring <code>PARAM_VALUE</code> as usual.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The file size reported in the <code>OpenFileRO</code> ACK is not reliable: because the packed length depends on the values themselves, ArduPilot returns an <em>estimate</em> (12 bytes per parameter) rather than computing the whole file up front. Clients must not use it to decide when the transfer is complete; the end of the file is the <code>EOF</code> NAK (or <code>burst_complete</code> followed by an <code>EOF</code> NAK). PX4 reports the exact length.</p></div><p>Because the entries carry the parameter type but not a <a href="./../messages/common.html#MAV_PARAM_TYPE">MAV_PARAM_TYPE</a>, a client that later writes one of these parameters with <code>PARAM_SET</code> must map the type itself (or, as <em>MAVProxy</em> does, send <code>MAV_PARAM_TYPE_REAL32</code> and rely on the component&#39;s own type lookup by name).</p><h2 id="ftp_upload" tabindex="-1">Uploading Parameters <a class="header-anchor" href="#ftp_upload" aria-label="Permalink to &quot;Uploading Parameters {#ftp_upload}&quot;">​</a></h2><p>ArduPilot also accepts a <em>write</em> to the same path, which sets many parameters in one transfer. This is used to restore a saved parameter file without a <code>PARAM_SET</code>/<code>PARAM_VALUE</code> round trip per parameter.</p><p>The uploaded file uses the same format with these differences:</p><ul><li><code>magic</code> must be <code>0x671B</code>; default values cannot be uploaded, and <code>flags</code> must be 0 in every entry.</li><li><code>total_params</code> is the <strong>total length of the file in bytes</strong>, not a parameter count. <code>num_params</code> is the number of entries.</li><li>No block padding is required or expected (the server parses the buffer as a whole once it is complete).</li></ul><p>The sequence is a standard FTP <a href="./../services/ftp.html#uploading-a-file">upload</a>: <code>CreateFile</code> on <code>@PARAM/param.pck</code>, a series of <code>WriteFile</code> commands, then <code>TerminateSession</code>. The parameters are applied when the session is closed, so an error in the file is reported as a NAK to the session-terminating command rather than to an individual write. Entries naming a parameter that does not exist, or that the component does not allow to be set over MAVLink, are silently skipped.</p><h2 id="ftp_limitations" tabindex="-1">Limitations <a class="header-anchor" href="#ftp_limitations" aria-label="Permalink to &quot;Limitations {#ftp_limitations}&quot;">​</a></h2><ul><li>The set of parameters is fixed when the file is opened, but the <em>values</em> are read live as blocks are generated. A parameter written while the download is in progress may be returned with either its old or its new value. The <a href="#ftp_padding">block padding</a> guarantees only that the value is never a mix of the two.</li><li>The <a href="./../services/parameter.html#parameters_invariant">parameter set must not change</a> during the download; if the component adds or removes parameters mid-transfer, the client must restart the sync.</li><li>The file has no integrity check of its own beyond the <code>magic</code> and the entry count, and relies on the FTP layer for delivery.</li><li>There is no notification mechanism: a client still has to monitor <code>PARAM_VALUE</code> to stay in sync after the download.</li></ul><h2 id="구현" tabindex="-1">구현 <a class="header-anchor" href="#구현" aria-label="Permalink to &quot;구현&quot;">​</a></h2><h3 id="px4" tabindex="-1">PX4 <a class="header-anchor" href="#px4" aria-label="Permalink to &quot;PX4&quot;">​</a></h3><p>PX4 supports <a href="#ftp_download">parameter <strong>download</strong> over MAVLink FTP</a>, serving <code>@PARAM/param.pck</code> with <code>INT32</code> and <code>FLOAT</code> entries and honouring <code>start</code>, <code>count</code> and <code>withdefaults</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 does not support parameter upload over FTP; a write to <code>@PARAM/param.pck</code> is rejected.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Added in <a href="https://github.com/PX4/PX4-Autopilot/pull/28435" target="_blank" rel="noreferrer">PX4-Autopilot#28435</a> (not yet in a stable release at time of writing).</p></div><h3 id="ardupilot" tabindex="-1">ArduPilot <a class="header-anchor" href="#ardupilot" aria-label="Permalink to &quot;ArduPilot&quot;">​</a></h3><p><a href="#ftp">Parameter download and upload over MAVLink FTP</a> is supported (ArduPilot originated this mechanism).</p><p>Source files:</p><ul><li><a href="https://github.com/ArduPilot/ardupilot/blob/master/libraries/AP_Filesystem/AP_Filesystem_Param.cpp" target="_blank" rel="noreferrer">libraries/AP_Filesystem/AP_Filesystem_Param.cpp</a> (packed parameter file)</li></ul><h3 id="qgroundcontrol" tabindex="-1">QGroundControl <a class="header-anchor" href="#qgroundcontrol" aria-label="Permalink to &quot;QGroundControl&quot;">​</a></h3><p><em>QGroundControl</em> first attempts a <a href="#ftp_download">parameter download over MAVLink FTP</a> from <a href="./../messages/common.html#MAV_COMP_ID_AUTOPILOT1">MAV_COMP_ID_AUTOPILOT1</a>, requesting <code>@PARAM/param.pck?withdefaults=1</code>, and falls back to <code>PARAM_REQUEST_LIST</code> if the file is not found or the transfer is too slow.</p>`,64)])])}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
